        {
            assistantMessageId: string;
            precedingUserId: string;
            mode: BranchMode;
        }
    ];
    'branch.retry:action:after': [
        {
            assistantMessageId: string;
            precedingUserId: string;
            newThreadId: string;
            mode: BranchMode;
        }
    ];
    'branch.context:filter:messages': [
        MessageEntity[],
        string /* threadId */,
        BranchMode
    ];
    'branch.context:action:after': [BranchContextAfterPayload];

    // Documents helpers
