    ) => void;
    applyFilters: <T>(name: string, value: T, ...args: unknown[]) => Promise<T>;
    applyFiltersSync: <T>(name: string, value: T, ...args: unknown[]) => T;

    addAction: <F extends HookFn>(
        name: string,
        fn: F,
        priority?: number,
        acceptedArgs?: number
    ) => void;
    removeAction: <F extends HookFn>(
        name: string,
        fn: F,
